"""Git and Agent Hook management for DevCity."""

import os
import pathlib
import stat
from typing import Tuple

PRE_COMMIT_HOOK_CONTENT = """#!/usr/bin/env bash
# DevCity Local Pre-Commit Guard (Secrets & Destructive Migrations)
# Generated by DevCity (https://github.com/sanjaydep1996/claude-code-usage-city)

set -e

# Run DevCity secret and safety check on staged changes
if command -v devcity >/dev/null 2>&1; then
  python3 -c "
import sys, subprocess
from devcity.guard.secrets import scan_git_diff

diff = subprocess.check_output(['git', 'diff', '--cached'], text=True, errors='ignore')
findings = scan_git_diff(diff)
dangers = [f for f in findings if f.severity == 'danger']
if dangers:
    print('\\n❌ DevCity Guard blocked commit due to security/destructive pattern findings:')
    for d in dangers:
        print(f'   • [{d.rule_id}] {d.message} (sample: {d.match_sample})')
    print('\\nTo bypass if intentional, run: git commit --no-verify\\n')
    sys.exit(1)
elif findings:
    print('\\n⚠️ DevCity Guard advisory warnings:')
    for f in findings:
        print(f'   • [{f.rule_id}] {f.message}')
"
fi
"""

CLAUDE_HOOK_CONTENT = """#!/usr/bin/env bash
# DevCity Claude Code Budget Warning Hook
# Warns developer in terminal if daily AI budget is near or exceeded

if command -v devcity >/dev/null 2>&1; then
  python3 -c "
import json, pathlib
p = pathlib.Path('data/usage.json')
if p.exists():
    try:
        d = json.loads(p.read_text())
        today = d.get('days', [{}])[-1]
        cost = today.get('costUSD', 0.0)
        if cost > 10.0:
            print(f'\\n⚠️ [DevCity Alert] Today AI tool spend is ${cost:.2f} (budget: $10.00)\\n')
    except Exception:
        pass
"
fi
"""


def install_git_hook(git_dir: pathlib.Path = pathlib.Path(".git")) -> Tuple[bool, str]:
    """Installs pre-commit safety hook into .git/hooks."""
    if not git_dir.exists():
        return False, f"Directory {git_dir} does not exist. Run inside a git repository."

    hooks_dir = git_dir / "hooks"
    hooks_dir.mkdir(parents=True, exist_ok=True)
    hook_path = hooks_dir / "pre-commit"

    hook_path.write_text(PRE_COMMIT_HOOK_CONTENT, encoding="utf-8")
    # Make executable
    st = os.stat(hook_path)
    os.chmod(hook_path, st.st_mode | stat.S_IEXEC | stat.S_IXGRP | stat.S_IXOTH)
    return True, f"Installed DevCity pre-commit hook at {hook_path}"


def install_claude_hook(dest_dir: pathlib.Path = pathlib.Path(".claude/hooks")) -> Tuple[bool, str]:
    """Installs Claude Code notification hook."""
    dest_dir.mkdir(parents=True, exist_ok=True)
    hook_path = dest_dir / "budget-warn.sh"
    hook_path.write_text(CLAUDE_HOOK_CONTENT, encoding="utf-8")
    st = os.stat(hook_path)
    os.chmod(hook_path, st.st_mode | stat.S_IEXEC | stat.S_IXGRP | stat.S_IXOTH)
    return True, f"Installed DevCity budget hook at {hook_path}"
